-- Class notes synopsis batch 10: Dong Quai through Eyebright

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Dong Quai</strong> (Angelica sinensis / Dang Gui) is a <strong>warming</strong>, <strong>moistening</strong>, <strong>anabolic</strong>, <strong>blood building</strong>, <strong>emmenagogue</strong>, and <strong>circulatory stimulant</strong> - a classic <strong>fertility</strong> herb that stimulates nourishment to the <strong>reproductive tissue</strong>, moves through periods of <strong>stagnation</strong>, and calms nerves and mind; also for <strong>sleep and relaxation</strong>. Specifically indicated for <strong>light or scant menses</strong> (hypomenorrhea/amenorrhea); in bi-phasic protocols, used weeks 1-2 (follicular phase) then rotate with <a href="?herb=190"><strong>Chasteberry</strong></a> weeks 3-4 (luteal) - "stimulates nourishment to the reproductive tissue." For <strong>PCOS</strong> ("Temple of Devotion" PCOS formula; blood movement); <strong>kidney deficiency</strong> (improves renal blood supply and hormonal stimulation); <strong>female reproductive deficiency</strong> as anabolic stimulant alongside <a href="?herb=72"><strong>Blue Cohosh</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, and <a href="?herb=14"><strong>Ginseng</strong></a>; <strong>male reproductive deficiency</strong> alongside <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, and Ginsengs to improve hormone use, pelvic circulation, and HPA axis (note: beer can influence sperm count). Blood building herbs for <strong>cold constitution</strong> alongside <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, and <a href="?herb=78"><strong>Licorice</strong></a>. Circulatory stimulant (blood and lymph) for <strong>cold constitution</strong> alongside <a href="?herb=123"><strong>Prickly Ash</strong></a>, <a href="?herb=47"><strong>Cayenne</strong></a>, <a href="?herb=35"><strong>Poke Root</strong></a> (lymph), <a href="?herb=70"><strong>Calendula</strong></a> (lymph), and <a href="?herb=1248"><strong>Ocotillo</strong></a> (lymph). For <strong>insulin sensitivity</strong>: TCM formula 5 parts Dang Gui to 1 part <a href="?herb=225"><strong>Astragalus</strong></a>. For <strong>Cold Dry Constipation</strong>: use as decoction. Topically (tincture or decoction) to increase <strong>photosensitivity</strong>; for <strong>dermatitis</strong> with <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, and <a href="?herb=2229"><strong>Gotu Kola</strong></a>. Preparation: fresh plant 1:2, dry root 1:5 60%; dose 10-60 drops 2-4x/day. <strong>Contraindicated for heavy menstrual bleeding - tissue builder that can aggravate heavy bleeding; avoid for fibroids. Also contraindicated with blood thinning agents and during pregnancy.</strong> When heavy bleeding is present, remove from formulas and shift dosage to <a href="?herb=2238"><strong>White Peony</strong></a>.$$
WHERE common_name = 'Dong Quai';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Echinacea</strong> is a <strong>pungent</strong>, <strong>immunostimulant</strong>, <strong>immunomodulator</strong>, <strong>antiviral</strong>, <strong>antimicrobial</strong>, <strong>vulnerary</strong>, <strong>lymphatic</strong>, and <strong>alterative</strong> herb - one of the most famous immunostimulants; modulates immunity primarily through <strong>glycoproteins</strong> that stimulate immune cell activation; tastes like sucking on a penny (<strong>sialogogue</strong>). Use at the <strong>onset of illness</strong> - immunostimulant right when you first get sick; immunomodulators are for when illness is further along; lower dose and less frequent during recovery; higher dose and more frequent right at onset. If "not working," may not be taking enough - need 2-3 droppers every 2-3 hours; effective antiviral dose is 3 droppers every 2 hours at first sign; or 1/4 tsp every hour until symptoms subside. For <strong>cold</strong>, <strong>flu</strong>, and <strong>viral infections</strong>: antiviral - interferes with virus ability to bind to cells. For <strong>sore throat</strong>: specifically noted for numbing effect; 60-90 drops every 3 hours. For <strong>hay fever</strong>: immunostimulant. For <strong>rheumatoid arthritis</strong>: immune modulator; main point is immune modulation and waste elimination. For <strong>microbial causes of diarrhea</strong> alongside Baptisia and <a href="?herb=33"><strong>Oregon Grape</strong></a>. For <strong>bacterial infections in feeble individuals</strong>: paired with <a href="?herb=35"><strong>Poke Root</strong></a> (also with Baptisia). For <strong>innate immunity</strong> in lymph/immune deficiency. <strong>Lymphatic</strong>: deep cleansing and draining, very strong, deep-seated action (noted alongside <a href="?herb=39"><strong>Figwort</strong></a> in lymphatic stagnation); <strong>antiseptic</strong> and <strong>analgesic</strong> (lymphatic) for <strong>cancer</strong> support; immune support for accumulation with aging. As <strong>alterative</strong> for <strong>hot constitution</strong>; alternative to <a href="?herb=225"><strong>Astragalus</strong></a> in damp or fungal conditions; also an alterative that reduces load on the liver (noted for snakebite). Topically for <strong>cuts and open wounds</strong> and <strong>infected wounds</strong>: antimicrobial, vulnerary, immune-stimulant (also taken internally for infected wounds). <strong>Safe during pregnancy</strong> - can be used preventatively; stimulates innate immune response; avoid roots in pregnancy; prefer nourishing broths as a more complete approach. Nice to mix with <a href="?herb=1651"><strong>Elder</strong></a> berry at onset. With <a href="?herb=99"><strong>Myrrh</strong></a> to stimulate immune function while addressing waste accumulation. In Getting Sick Blend with <a href="?herb=2229"><strong>Gotu Kola</strong></a>, <a href="?herb=981"><strong>Red Root</strong></a>, and <a href="?herb=1651"><strong>Elder</strong></a> berry glycerite.$$
WHERE common_name = 'Echinacea';

-- Elder id=57: flower
UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Elder</strong> flower (Sambucus) is a <strong>diaphoretic</strong> and <strong>antiviral</strong> - great for <strong>sinus conditions</strong> that are hot and stuck, with clogged ears, watery eyes, and <strong>allergies</strong>; excellent as a steam for <strong>congestion</strong>; promotes sweating to support <strong>fever</strong>. Listed as an antiviral immune stimulant with the power to destroy viral pathogens including <strong>common cold</strong>, <strong>flu</strong>, <strong>hepatitis</strong>, and <strong>HIV</strong>. For <strong>influenza</strong>: diaphoretic for fever and immunostimulant; elderflower syrup for children with fever. Bark is <strong>emetic</strong> for poisoning; leaf has peanut smell. Immune support for accumulation with aging. Note: poke berry can look like elderberry - identification caution.$$
WHERE id = 57;

-- Elder id=1651: berry
UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Elder</strong> berry (Sambucus) is an <strong>antiviral</strong>, <strong>immunostimulant</strong>, <strong>alterative</strong>, and <strong>lymphatic</strong> herb - one of the essential herbs of the Middle Ages in western Europe; listed in the African American Materia Medica; deeply revered in folklore; wild-harvested. Antiviral: inhibits viral replication and spread; can disarm a virus; best at the <strong>onset of sickness</strong>; for <strong>common cold</strong> and <strong>influenza</strong>. Also "cleanses" the blood and can help with <strong>skin conditions</strong>. A <strong>lymphatic</strong> herb for <strong>cancer</strong> support. Alterative: supports the body's natural mechanisms of detox and elimination. Use as elderberry syrup (amount depends on severity of sickness); pairs well with <a href="?herb=26"><strong>Echinacea</strong></a> at first sign of cold or flu; recommended for immune support and elderberry baths as fall self-care. <strong>Always dry berries before using.</strong> Note: poke berry can look like elderberry - identification caution. In Getting Sick Blend with <a href="?herb=26"><strong>Echinacea</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a>, and <a href="?herb=981"><strong>Red Root</strong></a>; tea blend for chemical sensitivity; optional add-in after Red Drank with <a href="?herb=73"><strong>Hawthorn</strong></a>. Immune decoction recipe (to 32 oz water): 28g Elderberries, 28g <a href="?herb=225"><strong>Astragalus</strong></a>, 14g <a href="?herb=124"><strong>Ginger</strong></a>.$$
WHERE id = 1651;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Elecampane</strong> (also known as Elfwort) is an <strong>expectorant</strong>, <strong>antitussive</strong>, <strong>antiviral</strong>, <strong>antimicrobial</strong>, <strong>bitter</strong>, and <strong>prebiotic</strong> (full of inulin) herb - a "swiss army knife for all constitutions"; both <strong>stimulating</strong> and <strong>relaxing</strong> expectorant; the mucilage has a relaxing effect while the EO brings stimulation - soothes irritation and promotes expectoration; usually double extracted; celery-tasting; cloudy tincture indicates inulin content. Targets <strong>deep lung structures</strong> - where the alveoli are gummed up and gas exchange is not happening properly; for <strong>fibrocystic pulmonary disease</strong>, <strong>bronchitis</strong>, <strong>pneumonia</strong>, <strong>emphysema</strong>, <strong>asthma</strong>, <strong>irritable coughs</strong>, and upper respiratory problems. Warming and drying for <strong>damp or cold respiratory conditions</strong>; also fits <strong>Hot and Dry Lung</strong> alongside <a href="?herb=61"><strong>Mullein</strong></a> and <a href="?herb=45"><strong>Marshmallow</strong></a> for cooling and moistening. Amphoteric for <strong>lung energetics</strong> (damp/dry) - match to constitution: dry for wet, wet for dry. Targets lungs but not cough specifically - if cough is present, add <a href="?herb=140"><strong>Wild Cherry Bark</strong></a>. As <strong>relaxing expectorant</strong> alongside <a href="?herb=61"><strong>Mullein</strong></a> and <a href="?herb=85"><strong>Plantain</strong></a>; <strong>antimicrobial</strong> alongside <a href="?herb=21"><strong>Garlic</strong></a>, <a href="?herb=59"><strong>Thyme</strong></a>, and <a href="?herb=112"><strong>Usnea</strong></a>; <strong>antiviral</strong> alongside <a href="?herb=21"><strong>Garlic</strong></a>. Inulin content provides <strong>prebiotic digestive support</strong>. In the Deep Lung Formula with <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=590"><strong>Yerba Santa</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a>, <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, and <a href="?herb=104"><strong>Osha</strong></a>. In sitz bath with <a href="?herb=70"><strong>Calendula</strong></a>, rose petals, and <a href="?herb=44"><strong>Yarrow</strong></a>. Digestion decoction recipe (to 32 oz water): 14g <a href="?herb=76"><strong>Fennel</strong></a>, 28g <a href="?herb=37"><strong>Yellow Dock</strong></a>, 28g Elecampane.$$
WHERE common_name = 'Elecampane';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>English Daisy</strong> combined with <a href="?herb=70"><strong>Calendula</strong></a> for <strong>wounds that don't heal</strong>; for animals: put herbal remedy in a little meatball for dogs, or in fish for cats to mask the smell.$$
WHERE common_name = 'English Daisy';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Eucalyptus</strong> is an <strong>amphoteric</strong>, <strong>alterative</strong>, <strong>hepatic</strong>, and <strong>nervine</strong> herb that supports <strong>pelvic circulation</strong> and <strong>lymphatic flow</strong> - recommended for buildup of waste in the <strong>large intestine</strong> causing sluggish immunity and lymph congestion. Used as steam inhalation (oil or fresh leaves) for <strong>respiratory congestion</strong> and <strong>bronchitis</strong> alongside Pine and <a href="?herb=59"><strong>Thyme</strong></a>. Also indicated in chemical sensitivity formulas.$$
WHERE common_name = 'Eucalyptus';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Evening Primrose</strong> oil is used internally for <strong>Poison Oak</strong> (itchy, hot, oozing skin reaction) and for <strong>premature gray hair</strong> recovery.$$
WHERE common_name = 'Evening Primrose';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Eyebright</strong> (Euphrasia) is an <strong>anticatarrhal</strong> herb for <strong>hay fever</strong>; really only works fresh (grows in UK). For <strong>skin excess</strong>: nerve cooling / decrease liver excitability.$$
WHERE common_name = 'Eyebright';
